const STADIUM_BY_NO = STADIUMS.reduce((acc, s) => {
  acc[s.no] = s.name;
  return acc;
}, {});

export function stadiumName(no) {
  return STADIUM_BY_NO[Number(no)] || (no ? `${no}場` : "―");
}

