import React, { useEffect, useMemo, useState } from "react";
import { findBoatsArray, F, ymdOf, fmtSt } from "../lib/api.js";
import { fetchRecentResults, buildCurrentMeetAll } from "../lib/aggregate.js";
import { CLASS_NAMES, BRANCH_NAMES, ABNORMAL_FINISH_LABELS, ABNORMAL_FINISH_NOTES } from "../constants.js";
import { LaneBadge, GradeBadge, TitleBadge, Notice, RawJson } from "./ui.jsx";
import RaceResultModal from "./RaceResultModal.jsx";

/** 今節成績を遡って取得する日数。開催は最長でも7日程度なので余裕を見て2週間分。 */
const MEET_LOOKBACK_DAYS = 16;
/** 今節成績の日付列1つぶんの幅。ヘッダーの「n日目」ラベルと揃える。 */
const DAY_COL_W = 46;

function Th({ children, w }) {
  return <th style={{ minWidth: w }} className="text-left font-normal py-1.5 px-2 text-sub2 whitespace-nowrap border border-line bg-panel">{children}</th>;
}
function Td({ children, align = "left", strong }) {
  const a = align === "right" ? "text-right" : align === "center" ? "text-center" : "text-left";
  return <td className={`py-1.5 px-2 whitespace-nowrap tabular-nums border border-line ${a} ${strong ? "font-semibold text-ink" : "text-sub"}`}>{children}</td>;
}

/** 級別/支部を「A1/大阪」のような読める表記にする。 */
function classAndBranch(b) {
  const cls = CLASS_NAMES[Number(F.racerClass(b))] || "―";
  const branch = BRANCH_NAMES[Number(F.branch(b))] || "―";
  return `${cls} / ${branch}`;
}

/** 今節成績を1レースぶんのミニカードとして表示する。クリックでそのレースの結果を開く。 */
function MeetChip({ row, onOpen }) {
  const abnormal = row.place !== undefined && row.place !== null && !(row.place >= 1 && row.place <= 6);
  return (
    <button
      onClick={() => onOpen(row)}
      className="shrink-0 bg-base border border-line rounded px-1.5 py-1 text-center leading-tight hover:border-accent transition-colors"
      title={abnormal && row.abnormalCode ? ABNORMAL_FINISH_NOTES[row.abnormalCode] : undefined}
    >
      <div className="text-[8px] text-weak">{row.raceNo}R</div>
      <div className="flex items-center justify-center gap-1 mt-0.5">
        <LaneBadge lane={row.course} size="xs" />
        <span className="text-[11px] font-bold" style={{ color: abnormal ? "#E5433D" : row.place === 1 ? "#F2A93B" : "#EAF1F7" }}>
          {abnormal ? (ABNORMAL_FINISH_LABELS[row.abnormalCode] || "失格") : row.place ? `${row.place}着` : "―"}
        </span>
      </div>
      <div className="text-[8px] text-sub2 tabular-nums mt-0.5">
        ST{fmtSt(row.st)}{row.stRank ? `（${row.stRank}/${row.fieldSize}）` : ""}
      </div>
    </button>
  );
}

/**
 * 今節成績を日付ごとの列に並べる。「1日目」「2日目」…のラベルは表の
 * ヘッダー側（今節成績の見出しの下）に1回だけ出すので、ここでは出さない。
 * 選手ごとに欠場日があってもヘッダーと列がズレないよう、節の全開催日
 * ぶんの列を必ず並べ、その選手の出走が無い日は空欄にする。
 * 同日に複数走ある場合は縦に積む。
 */
function MeetHistory({ rows, loading, onOpen, days }) {
  if (!days.length) {
    return <span className="text-[10px] text-weak py-1">{loading ? "取得中…" : "今節の出走データがありません"}</span>;
  }
  const byYmd = new Map();
  for (const r of rows) {
    if (!byYmd.has(r.ymd)) byYmd.set(r.ymd, []);
    byYmd.get(r.ymd).push(r);
  }
  return (
    <div className="flex gap-1">
      {days.map((ymd) => {
        const dayRows = byYmd.get(ymd) || [];
        return (
          <div key={ymd} style={{ width: DAY_COL_W }} className="shrink-0 flex flex-col items-center gap-1">
            {dayRows.length
              ? dayRows.map((r, k) => <MeetChip key={k} row={r} onOpen={onOpen} />)
              : <span className="text-[9px] text-weak">―</span>}
          </div>
        );
      })}
    </div>
  );
}

/**
 * 出走表: 基本情報＋今節成績を1枚の横スクロール表に統合。
 * 選手名列は横スクロール時も左に固定表示し、クリックすると
 * 選手の節間成績・過去走データ（公式サイトからその場で取得）をモーダル表示する。
 */
export default function ProgramsTable({ race, grade, onOpenRacer, stadium, date }) {
  const [meetByRacer, setMeetByRacer] = useState({});
  const [meetLoading, setMeetLoading] = useState(false);
  const [openRace, setOpenRace] = useState(null);

  const ymd = date ? ymdOf(date) : null;
  const raceNo = F.raceNo(race);

  useEffect(() => {
    if (!stadium || !ymd) {
      setMeetByRacer({});
      return;
    }
    let alive = true;
    const ac = new AbortController();
    setMeetLoading(true);
    (async () => {
      try {
        const all = await fetchRecentResults(MEET_LOOKBACK_DAYS, {
          signal: ac.signal,
          fromDate: date,
          includeFromDate: true,
        });
        if (!alive) return;
        setMeetByRacer(buildCurrentMeetAll(all, stadium, ymd, { excludeRaceNo: raceNo }));
      } catch {
        if (alive) setMeetByRacer({});
      } finally {
        if (alive) setMeetLoading(false);
      }
    })();
    return () => {
      alive = false;
      ac.abort();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [stadium, ymd, raceNo]);

  // 今節の実際の開催日（全選手の出走日の和集合）。「1日目」「2日目」…はこの
  // 並びをもとに表のヘッダー側で1回だけ表示し、各選手の行はこれに合わせて並べる。
  const meetDays = useMemo(() => {
    const allYmd = new Set();
    for (const rows of Object.values(meetByRacer)) for (const r of rows) allYmd.add(r.ymd);
    return [...allYmd].sort();
  }, [meetByRacer]);

  if (!race) return <Notice>この日・このレースの出走表データが見つかりません。</Notice>;
  const boats = findBoatsArray(race);
  if (!boats.length) return <Notice>選手情報が見つかりませんでした。生JSONで構造を確認してください。</Notice>;

  return (
    <div>
      <div className="flex items-center flex-wrap gap-1.5 text-xs text-sub mb-2">
        <GradeBadge grade={grade} />
        <TitleBadge title={F.raceSubtitle(race)} />
        {F.distance(race) && <span>{F.distance(race)}m</span>}
        {F.closedAt(race) && <span>締切 {F.closedAt(race)}</span>}
      </div>

      <div className="scroll-x -mx-4 px-4">
        {/*
          横スクロール中、選手名列（sticky）の罫線が他列とズレて見えるのは
          border-collapse + position:sticky の組み合わせで起きる既知の描画崩れ。
          border-separate + border-spacing:0 にして回避する。
        */}
        <table className="border-separate text-[11px] min-w-[1080px]" style={{ borderSpacing: 0 }}>
          <thead>
            <tr>
              <Th w={150}>選手</Th>
              <Th w={80}>級/支部</Th>
              <Th w={78}>年齢/体重</Th>
              <Th w={44}>F/L</Th>
              <Th w={118}>全国 勝率/2連/3連</Th>
              <Th w={118}>当地 勝率/2連/3連</Th>
              <Th w={90}>モーター 2連/3連</Th>
              <Th w={90}>ボート 2連/3連</Th>
              <Th w={58}>平均ST</Th>
              <th
                style={{ minWidth: Math.max(260, meetDays.length * (DAY_COL_W + 4)) }}
                className="text-left font-normal py-1.5 px-2 text-sub2 border border-line bg-panel align-top"
              >
                <div className="whitespace-nowrap">今節成績</div>
                {meetDays.length > 0 && (
                  <div className="flex gap-1 mt-1">
                    {meetDays.map((ymd, i) => (
                      <div key={ymd} style={{ width: DAY_COL_W }} className="shrink-0 text-center text-[8px] font-normal text-weak whitespace-nowrap">
                        {i + 1}日目
                      </div>
                    ))}
                  </div>
                )}
              </th>
            </tr>
          </thead>
          <tbody>
            {boats.map((b, i) => {
              const lane = F.lane(b, i);
              const racerNo = F.racerNo(b);
              const fl = F.flying(b), lt = F.late(b);
              const name = F.racerName(b) ?? "―";
              const meet = meetByRacer[racerNo] || [];

              return (
                <tr key={lane} className="hover:bg-panel/60">
                  <td className="py-1.5 px-2 sticky left-0 bg-base border border-line" style={{ zIndex: 1 }}>
                    <div className="flex items-center gap-1.5">
                      <LaneBadge lane={lane} size="sm" />
                      <button
                        onClick={() => onOpenRacer({ lane, racerNo, name })}
                        className="font-semibold text-ink whitespace-nowrap underline decoration-dotted underline-offset-2 hover:text-accent"
                      >
                        {name}
                      </button>
                    </div>
                    <div className="text-[9px] text-weak mt-0.5">{racerNo ?? ""}</div>
                  </td>
                  <Td>{classAndBranch(b)}</Td>
                  <Td>{F.age(b) ? `${F.age(b)}歳` : "―"} / {F.weight(b) ? `${F.weight(b)}kg` : "―"}</Td>
                  <Td>{fl > 0 || lt > 0 ? <span className="font-bold text-[#E5433D]">{fl > 0 ? `F${fl}` : ""}{lt > 0 ? `L${lt}` : ""}</span> : "―"}</Td>
                  <Td strong>{F.natWin(b) ?? "―"} / {F.natTop2(b) ?? "―"}% / {F.natTop3(b) ?? "―"}%</Td>
                  <Td strong>{F.locWin(b) ?? "―"} / {F.locTop2(b) ?? "―"}% / {F.locTop3(b) ?? "―"}%</Td>
                  <Td>{F.motorTop2(b) ?? "―"}% / {F.motorTop3(b) ?? "―"}%</Td>
                  <Td>{F.boatTop2(b) ?? "―"}% / {F.boatTop3(b) ?? "―"}%</Td>
                  <Td align="right" strong>{fmtSt(F.avgSt(b))}</Td>
                  <td className="py-1.5 px-2 border border-line">
                    <MeetHistory rows={meet} loading={meetLoading} onOpen={setOpenRace} days={meetDays} />
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <div className="mt-2 text-[10px] text-weak leading-relaxed">
        横にスクロールすると全項目が見られます。今節成績は表内の主催BoatraceOpenAPIから自動取得した参考値です。選手名をクリックすると節間成績・過去走を表示します。今節成績のマスをクリックするとそのレースの結果を表示します。
      </div>
      <RawJson data={race} />

      {openRace && (
        <RaceResultModal
          race={openRace.raceRef}
          stadiumNo={stadium}
          ymd={openRace.ymd}
          raceNo={openRace.raceNo}
          onClose={() => setOpenRace(null)}
        />
      )}
    </div>
  );
}
