import React, { useEffect, useState } from "react";
import { Wind, Droplets, Thermometer, WavesHorizontal, Loader2 } from "lucide-react";
import { findBoatsArray, F, fmtSt, PROXY_BASE } from "../lib/api.js";
import { LaneBadge, Notice, RawJson } from "./ui.jsx";

function Chip({ icon, label, value, unit }) {
  return (
    <div className="flex flex-col items-center gap-0.5 bg-panel border border-line rounded-lg py-1.5">
      <div className="text-accent">{icon}</div>
      <span className="text-[9px] text-sub2">{label}</span>
      <span className="text-xs font-semibold tabular-nums text-ink">
        {value === undefined || value === null || value === "" ? "―" : `${value}${unit}`}
      </span>
    </div>
  );
}

function Th({ children, w }) {
  return <th style={{ minWidth: w }} className="text-left font-normal py-1.5 px-2 text-sub2 whitespace-nowrap border border-line bg-panel">{children}</th>;
}
function Td({ children, align = "right", bg }) {
  const a = align === "right" ? "text-right" : align === "center" ? "text-center" : "text-left";
  return (
    <td className={`py-1.5 px-2 whitespace-nowrap tabular-nums border border-line text-ink ${a}`} style={bg ? { background: bg } : undefined}>
      {children}
    </td>
  );
}
function cellText(v, unit = "") {
  return v === undefined || v === null || v === "" ? "―" : `${v}${unit}`;
}

function byLane(rows) {
  const map = {};
  for (const r of rows || []) map[r.lane] = r;
  return map;
}

/** 展示タイム上位3艇に付ける薄い色（1位=赤/2位=だいだい/3位=黄）。 */
const EXHIBITION_RANK_BG = {
  1: "rgba(229, 67, 61, 0.16)",
  2: "rgba(242, 130, 61, 0.16)",
  3: "rgba(242, 196, 56, 0.16)",
};

/** 展示タイムの速い順に上位3艇の枠番→順位を返す。 */
function rankByExhibitionTime(boats) {
  const times = boats
    .map((b, i) => ({ lane: F.lane(b, i), t: parseFloat(F.exhibitionTime(b)) }))
    .filter((x) => Number.isFinite(x.t));
  times.sort((a, b) => a.t - b.t);
  const map = {};
  times.slice(0, 3).forEach((x, i) => { map[x.lane] = i + 1; });
  return map;
}

/**
 * BOATCAST（race.boatcast.jp）から、boatrace.jp/BoatraceOpenAPI には
 * 無い「スタート展示（進入コース・展示ST）」「オリジナル展示（周回・
 * まわり足・直線タイム。公表しているレース場のみ）」「体重差（前走比）」
 * を取得する。取得用プロキシ（lib/api.js の PROXY_BASE）が必要。
 * サーバーが動いていない等で丸ごと失敗した場合のみ控えめに注記を出し、
 * 個別のデータ種別が単に「その場が公表していない」だけの場合は
 * 該当セクションを静かに省略する。
 */
function useBoatcastBeforeInfo(stadium, raceNo, ymd) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    setData(null);
    setError(null);
    if (!stadium || !raceNo || !ymd) return;
    let alive = true;
    const ac = new AbortController();
    setLoading(true);
    (async () => {
      try {
        const url = `${PROXY_BASE}/api/beforeinfo?stadium=${stadium}&hd=${ymd}&rno=${raceNo}`;
        const res = await fetch(url, { signal: ac.signal });
        const json = await res.json().catch(() => null);
        if (!alive) return;
        if (!res.ok || !json) throw new Error(json?.error || `HTTP ${res.status}`);
        setData(json);
      } catch (e) {
        if (alive && e?.name !== "AbortError") setError(String(e.message || e));
      } finally {
        if (alive) setLoading(false);
      }
    })();
    return () => {
      alive = false;
      ac.abort();
    };
  }, [stadium, raceNo, ymd]);

  return { data, loading, error };
}

export default function PreviewsPanel({ race, boatNames, stadium, raceNo, ymd }) {
  const { data: bc, loading: bcLoading, error: bcError } = useBoatcastBeforeInfo(stadium, raceNo, ymd);

  if (!race) {
    return <Notice>直前情報はまだ公開されていないか、この日付は対応期間外です。直前情報は各レースの開始1時間前後に公開されます。</Notice>;
  }
  const boats = findBoatsArray(race);

  // BoatraceOpenAPIは発表前でも気温等を0で返してくるため、展示タイムが
  // 1つも無く気象値も全て0（≒未取得）なら「まだ発表されていない」とみなす。
  const hasExhibitionTime = boats.some((b) => {
    const v = F.exhibitionTime(b);
    return v !== undefined && v !== null && v !== "";
  });
  const hasWeather = [F.airTemp(race), F.waterTemp(race), F.windSpeed(race), F.wave(race)].some((v) => Number(v) > 0);
  const isPublished = hasExhibitionTime || hasWeather;

  if (!isPublished) {
    return <Notice>この日・このレースの直前情報はまだ発表されていません。各レースの開始1時間前後に発表されます。</Notice>;
  }

  const startByLane = byLane(bc?.startExhibition);
  const origByLane = byLane(bc?.originalExhibition);
  const preByLane = byLane(bc?.preRaceInfo);
  const hasOriginal = Object.values(origByLane).some((o) => o.lap || o.turn || o.straight);
  const exhibitionRanks = rankByExhibitionTime(boats);

  return (
    <div>
      <div className="grid grid-cols-4 gap-2 mb-3">
        <Chip icon={<Thermometer size={14} />} label="気温" value={F.airTemp(race)} unit="℃" />
        <Chip icon={<Wind size={14} />} label={F.windDir(race) ? `風(${F.windDir(race)})` : "風速"} value={F.windSpeed(race)} unit="m" />
        <Chip icon={<WavesHorizontal size={14} />} label="波高" value={F.wave(race)} unit="cm" />
        <Chip icon={<Droplets size={14} />} label="水温" value={F.waterTemp(race)} unit="℃" />
      </div>
      {F.weather(race) && <div className="text-xs text-sub mb-3">天候：{F.weather(race)}</div>}

      {bcLoading && (
        <div className="flex items-center gap-1.5 text-[10px] text-sub2 mb-2">
          <Loader2 size={11} className="animate-spin" />BOATCASTからスタート展示・オリジナル展示を取得中…
        </div>
      )}
      {bcError && !bcLoading && (
        <div className="text-[10px] text-weak mb-2 leading-relaxed">
          スタート展示・オリジナル展示は取得できませんでした（取得用プロキシが動いているか確認してください）。基本の直前情報は引き続き表示します。
        </div>
      )}

      {!boats.length && <Notice>展示情報が見つかりませんでした。生JSONで構造を確認してください。</Notice>}

      {boats.length > 0 && (
        <div className="scroll-x -mx-4 px-4">
          <table className="border-separate text-[11px]" style={{ borderSpacing: 0 }}>
            <thead>
              <tr>
                <Th w={140}>選手</Th>
                <Th w={64}>進入</Th>
                <Th w={72}>展示タイム</Th>
                <Th w={56}>チルト</Th>
                <Th w={64}>体重</Th>
                <Th w={64}>展示ST</Th>
                <Th w={90}>体重差(前走比)</Th>
                {hasOriginal && <Th w={56}>1周</Th>}
                {hasOriginal && <Th w={72}>まわり足</Th>}
                {hasOriginal && <Th w={64}>直線</Th>}
              </tr>
            </thead>
            <tbody>
              {boats.map((b, i) => {
                const lane = F.lane(b, i);
                const st = startByLane[lane];
                const orig = origByLane[lane];
                const pre = preByLane[lane];
                return (
                  <tr key={lane} className="hover:bg-panel/60">
                    <td className="py-1.5 px-2 sticky left-0 bg-base border border-line" style={{ zIndex: 1 }}>
                      <div className="flex items-center gap-1.5">
                        <LaneBadge lane={lane} size="sm" />
                        <span className="font-semibold text-ink whitespace-nowrap truncate max-w-[8rem]">
                          {F.racerName(b) ?? boatNames?.[lane - 1] ?? "―"}
                        </span>
                      </div>
                    </td>
                    <Td align="center">{cellText(F.courseNo(b))}</Td>
                    <Td bg={EXHIBITION_RANK_BG[exhibitionRanks[lane]]}>{cellText(F.exhibitionTime(b))}</Td>
                    <Td>{cellText(F.tilt(b))}</Td>
                    <Td>{cellText(F.beforeWeight(b), "kg")}</Td>
                    <Td>{st?.st ? fmtSt(st.st) : "―"}</Td>
                    <Td>{cellText(pre?.weightDiff)}</Td>
                    {hasOriginal && <Td>{cellText(orig?.lap)}</Td>}
                    {hasOriginal && <Td>{cellText(orig?.turn)}</Td>}
                    {hasOriginal && <Td>{cellText(orig?.straight)}</Td>}
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      <div className="mt-3 flex items-center gap-3 text-[9px] text-weak">
        <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-sm" style={{ background: EXHIBITION_RANK_BG[1] }} />展示1位</span>
        <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-sm" style={{ background: EXHIBITION_RANK_BG[2] }} />2位</span>
        <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-sm" style={{ background: EXHIBITION_RANK_BG[3] }} />3位</span>
      </div>
      <div className="mt-1.5 text-[10px] text-weak leading-relaxed">
        展示ST・体重差(前走比)・オリジナル展示（1周/まわり足/直線）はBOATCASTから取得した参考値です。オリジナル展示は公表しているレース場のみ表示されます{!bcLoading && bc && !hasOriginal && "（この場は非公開のようです）"}。
      </div>
      <RawJson data={race} />
    </div>
  );
}
